void angle_diagnostic(cudaStream_t s){
 const float base=std::pow(10000.f,-2.f/64);Gpu buf(8*4);auto* result=buf.as<float>();
 ck(backend::submit(s,[=](sycl::queue& q){return q.single_task([=]{const float power=::powf(base,1.f),angle=40.f*power;result[0]=base;result[1]=power;result[2]=angle;result[3]=::cosf(angle);result[4]=::sinf(angle);result[5]=sycl::ext::intel::math::ha::pow(base,1.f);result[6]=40.f*result[5];});}));
 auto got=buf.get<float>(s);const float power=std::pow(base,1.f),angle=40.f*power;
 std::cerr<<std::hexfloat<<"angle diagnostic gpu base/power/theta/cos/sin="<<got[0]<<" "<<got[1]<<" "<<got[2]<<" "<<got[3]<<" "<<got[4]<<" IMF-HA power/theta="<<got[5]<<" "<<got[6]<<" cpu="<<base<<" "<<power<<" "<<angle<<" "<<std::cos(double(angle))<<" "<<std::sin(double(angle))<<std::defaultfloat<<'\n';
}
